  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Railroads, Inventors and Big Business$j$, $j${"readings": [{"title": "Proverbs 10 (King James Version)", "url": "/portal/bible/Proverbs/10"}], "body": "After the Civil War the United States changed from a mostly farming nation into the world's leading industrial power. Mark Twain called this time the Gilded Age, meaning a thin gold coating over serious problems underneath.\n\nRailroads led the way. The Transcontinental Railroad was completed at Promontory, Utah, in 1869, joining East and West. Railroads created national markets, built towns and used huge amounts of steel and coal. Inventors added to the growth: Alexander Graham Bell patented the telephone in 1876, and Thomas Edison perfected a practical light bulb in 1879 and built a research laboratory. Lewis Latimer, an African American inventor and draftsman, improved the light bulb filament.\n\nGreat business leaders rose. Andrew Carnegie built a steel empire and later gave away most of his fortune to libraries and schools. John D. Rockefeller built Standard Oil. J. P. Morgan organized banks and railroads. Some admired them as captains of industry. Critics called them robber barons for crushing competition and underpaying workers. Monopolies and trusts concentrated power, so Congress passed the Sherman Antitrust Act in 1890.\n\nProverbs 10:4 says, He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.\n\nYour task: (1) Tell two effects of the railroads. (2) Name two inventors and their inventions. (3) Explain the argument for and against calling business leaders captains of industry or robber barons.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome to Unit 2. Listen, after the Civil War the United States changed from a mostly farming nation into the world's leading industrial power. Mark Twain called this time the Gilded Age, a thin gold coating over serious problems underneath.\n\nNow watch this. Railroads led the way. The Transcontinental Railroad was finished at Promontory, Utah, in eighteen sixty nine, joining East and West. Railroads built national markets and towns and used huge amounts of steel and coal. Inventors added to the growth. Alexander Graham Bell patented the telephone in eighteen seventy six. Thomas Edison perfected a practical light bulb in eighteen seventy nine and built a research laboratory. Lewis Latimer, an African American inventor, improved the filament.\n\nLook at this. Great business leaders rose. Andrew Carnegie built steel and later gave away most of his fortune to libraries and schools. John D. Rockefeller built Standard Oil. J. P. Morgan organized banks and railroads. Some called them captains of industry. Critics called them robber barons for crushing competition and underpaying workers. Monopolies and trusts concentrated power, so Congress passed the Sherman Antitrust Act in eighteen ninety.\n\nProverbs ten and four says, He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.\n\nYour task today. Tell two effects of the railroads. Name two inventors and their inventions. And explain the argument for and against the labels captains of industry and robber barons. Take the four question check.\n\nWealth is a trust before God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Railroads, Inventors and Big Business$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Workers, Unions and Strikes$j$, $j${"readings": [{"title": "Leviticus 19 (King James Version)", "url": "/portal/bible/Leviticus/19"}], "body": "Industry created wealth, but many workers faced hard conditions. Factory workers often labored ten to twelve hours a day, six days a week, for low pay. Child labor was common, and accidents in mines and mills killed or injured thousands. There was no insurance or pension.\n\nWorkers organized unions to bargain together. The Knights of Labor grew in the 1880s and welcomed many kinds of workers. The American Federation of Labor, founded in 1886 under Samuel Gompers, focused on skilled workers and asked for better wages, shorter hours and safer conditions.\n\nMajor clashes showed the struggle:\nThe Haymarket Affair in Chicago in 1886 began as a rally for an eight hour day and ended when a bomb killed police officers and others, leading to fear of unions.\nThe Homestead Strike of 1892 at Carnegie's steel plant ended in a deadly fight with private guards.\nThe Pullman Strike of 1894, led by Eugene Debs, spread across the nation's railroads until President Grover Cleveland sent federal troops.\n\nEmployers often used court orders, blacklists and force. Unions grew slowly but their ideas, such as the eight hour day, later became law. Leviticus 19:13 says, Thou shalt not defraud thy neighbour, neither rob him: the wages of him that is hired shall not abide with thee all night until the morning.\n\nYour task: (1) Describe two hardships of factory workers. (2) Compare the Knights of Labor and the AFL. (3) Explain one strike and its result.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome back. Listen, industry created wealth, but many workers faced hard conditions. Factory workers often labored ten to twelve hours a day, six days a week, for low pay. Child labor was common, and accidents in mines and mills killed or injured thousands. There was no insurance and no pension.\n\nNow watch this. Workers organized unions to bargain together. The Knights of Labor grew in the eighteen eighties and welcomed many kinds of workers. The American Federation of Labor, founded in eighteen eighty six under Samuel Gompers, focused on skilled workers and asked for better wages, shorter hours and safer conditions.\n\nLook at this. Major clashes showed the struggle. The Haymarket Affair in Chicago in eighteen eighty six began as a rally for an eight hour day and ended when a bomb killed police officers and others, which led to fear of unions. The Homestead Strike of eighteen ninety two at Carnegie's steel plant ended in a deadly fight with private guards. The Pullman Strike of eighteen ninety four, led by Eugene Debs, spread across the railroads until President Cleveland sent federal troops.\n\nEmployers often used court orders, blacklists and force. Unions grew slowly, but ideas like the eight hour day later became law. Leviticus nineteen and thirteen says, Thou shalt not defraud thy neighbour, neither rob him: the wages of him that is hired shall not abide with thee all night until the morning.\n\nYour task today. Describe two hardships of factory workers. Compare the Knights of Labor and the AFL. And explain one strike and its result. Take the four question check.\n\nGod cares about fair wages. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Workers, Unions and Strikes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Immigration and the Growth of Cities$j$, $j${"readings": [{"title": "Exodus 22 (King James Version)", "url": "/portal/bible/Exodus/22"}], "body": "Between 1870 and 1920 more than 25 million immigrants came to the United States. Earlier groups had come from Britain, Ireland and Germany. The new immigrants came from southern and eastern Europe, including Italy, Poland and Russia, and many Jewish families fled persecution. Their reasons were poverty, hunger, war and religious persecution at home, and hope for work and freedom here.\n\nMost European immigrants entered through Ellis Island in New York harbor, opened in 1892, near the Statue of Liberty, a gift from France dedicated in 1886. Asian immigrants entered through Angel Island in San Francisco, where they were often held for long questioning. Many immigrants settled in cities and worked in factories and mines.\n\nCities grew fast. Crowded tenements, poor sanitation and disease were common. Reformers such as Jacob Riis photographed slum life, and Jane Addams opened Hull House in Chicago to help immigrants with education and child care. Streetcars, skyscrapers and department stores changed city life.\n\nSome Americans welcomed newcomers; others, called nativists, feared them. The Chinese Exclusion Act of 1882 banned Chinese laborers, the first major law to ban a group by nationality. Exodus 22:21 says, Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt.\n\nYour task: (1) Give two push reasons and one pull reason for immigration. (2) Contrast Ellis Island and Angel Island. (3) Tell one way reformers helped city dwellers.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome back. Listen, between eighteen seventy and nineteen twenty more than twenty five million immigrants came to the United States. Earlier groups came from Britain, Ireland and Germany. The new immigrants came from southern and eastern Europe, Italy, Poland and Russia, and many Jewish families fled persecution. They came because of poverty, hunger, war and persecution at home, and hope for work and freedom here.\n\nNow watch this. Most European immigrants entered through Ellis Island in New York harbor, opened in eighteen ninety two, near the Statue of Liberty, a gift from France dedicated in eighteen eighty six. Asian immigrants entered through Angel Island in San Francisco, where they were often held for long questioning. Many immigrants settled in cities and worked in factories and mines.\n\nLook at this. Cities grew fast. Crowded tenements, poor sanitation and disease were common. Jacob Riis photographed slum life, and Jane Addams opened Hull House in Chicago to help immigrants with education and child care. Some Americans welcomed newcomers; others, called nativists, feared them. The Chinese Exclusion Act of eighteen eighty two banned Chinese laborers, the first major law to ban a group by nationality.\n\nExodus twenty two and twenty one says, Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt.\n\nYour task today. Give two push reasons and one pull reason for immigration. Contrast Ellis Island and Angel Island. And tell one way reformers helped city dwellers. Take the four question check.\n\nWelcome the stranger with justice and love. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Immigration and the Growth of Cities$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Westward Expansion, Native Americans and the Farmers' Revolt$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}], "body": "After the Civil War settlers moved west in great numbers. The Homestead Act of 1862 gave 160 acres to families who farmed the land for five years. Railroads sold land and carried cattle, wheat and people. African American families known as Exodusters moved to Kansas, and cowboys drove cattle along trails to rail towns.\n\nFor Native Americans the expansion brought loss. The government made treaties and broke many of them. Settlers killed millions of buffalo, the foundation of Plains life. Battles such as Sand Creek (1864), Little Bighorn (1876) where Sioux and Cheyenne warriors defeated Colonel Custer, and the flight of the Nez Perce in 1877 ended with removal to reservations. At Wounded Knee in 1890 soldiers killed about 150 Lakota men, women and children. The Dawes Act of 1887 broke up tribal lands, and boarding schools tried to erase Native languages and customs. These were grievous wrongs that Christians should acknowledge with honesty and sorrow.\n\nBy 1890 the Census Bureau said the frontier was closed. Farmers faced falling crop prices, high railroad rates and debt. They joined the Grange and then the Populist Party in 1892. In 1896 William Jennings Bryan spoke for farmers in his Cross of Gold speech, but he lost the election to William McKinley.\n\nPsalm 24:1 says, The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein.\n\nYour task: (1) Tell what the Homestead Act offered. (2) Explain two ways westward expansion harmed Native Americans. (3) Describe why farmers joined the Populists.\n\nFlorida standards: SS.912.A.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.3", "script": "Welcome back. Listen, after the Civil War settlers moved west in great numbers. The Homestead Act of eighteen sixty two gave one hundred sixty acres to families who farmed the land for five years. Railroads sold land and carried cattle, wheat and people. African American families called Exodusters moved to Kansas, and cowboys drove cattle to rail towns.\n\nNow watch this. For Native Americans the expansion brought loss. The government made treaties and broke many of them. Settlers killed millions of buffalo, the foundation of Plains life. At Little Bighorn in eighteen seventy six, Sioux and Cheyenne warriors defeated Colonel Custer, but the wars ended with removal to reservations. At Wounded Knee in eighteen ninety soldiers killed about one hundred fifty Lakota men, women and children. The Dawes Act of eighteen eighty seven broke up tribal lands, and boarding schools tried to erase Native languages and customs. These were grievous wrongs that Christians should acknowledge with honesty and sorrow.\n\nLook at this. By eighteen ninety the Census Bureau said the frontier was closed. Farmers faced falling crop prices, high railroad rates and debt. They joined the Grange and then the Populist Party in eighteen ninety two. In eighteen ninety six William Jennings Bryan spoke for farmers in his Cross of Gold speech, but he lost to William McKinley.\n\nPsalm twenty four and one says, The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein.\n\nYour task today. Tell what the Homestead Act offered. Explain two ways westward expansion harmed Native Americans. And describe why farmers joined the Populists. Take the four question check.\n\nThe land belongs to God, and we are stewards. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Westward Expansion, Native Americans and the Farmers' Revolt$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Progress and Problems of the Gilded Age$j$, $j${"prompt": "Write an essay answering this question: Was the Gilded Age a time of progress, a time of problems, or both? Use complete sentences and label each part. Leviticus 19:13 says, Thou shalt not defraud thy neighbour, neither rob him: the wages of him that is hired shall not abide with thee all night until the morning.\n\nPart 1: Describe three developments in industry and invention and explain how each changed life.\nPart 2: Describe working conditions and explain two ways workers tried to improve them.\nPart 3: Explain why immigrants came, how they were treated, and how cities changed.\nPart 4: Explain what happened to Native Americans in the West and give one cause of that conflict.\nPart 5: Explain why farmers were unhappy and what the Populists wanted.\nPart 6: Give your thesis, with evidence from at least four parts of this unit, on whether the Gilded Age was mostly progress or mostly problems, and apply one KJV verse.", "rubric": "70 points. Industry and invention: 10 points. Workers and unions: 10 points. Immigrants and cities: 10 points. Native Americans: 10 points. Farmers and Populists: 8 points. Thesis and evidence: 18 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Progress and Problems of the Gilded Age$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Wealth, Work and Welcome$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains how railroads and inventions changed American life, (2) tells how a Christian employer should treat workers in light of Leviticus 19:13, (3) describes how the nation treated immigrants or Native Americans in this period and what we should learn, and (4) connects your answer to Exodus 22:21, which says, Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt. Then write a respectful reply of at least 40 words to another student, or answer this question: Why did workers form unions? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Wealth, Work and Welcome$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Railroads, Inventors and Big Business$j$, $j${"questions": [{"q": "The Transcontinental Railroad was completed in:", "options": ["1929", "1869", "1776", "1898"]}, {"q": "Who patented the telephone in 1876?", "options": ["Samuel Morse", "Thomas Edison", "Alexander Graham Bell", "Henry Ford"]}, {"q": "Andrew Carnegie is known for:", "options": ["Steel and later giving to libraries", "The telephone", "Railroad robbery", "Standard Oil"]}, {"q": "The Sherman Antitrust Act (1890) was meant to:", "options": ["Protect immigrants", "End slavery", "Create income tax", "Limit monopolies and trusts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Railroads, Inventors and Big Business$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,3}'::int[], array[$j$The golden spike was driven at Promontory, Utah.$j$,$j$Bell's telephone changed communication.$j$,$j$He built a steel empire and funded public libraries.$j$,$j$It aimed to protect competition.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Railroads, Inventors and Big Business$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Workers, Unions and Strikes$j$, $j${"questions": [{"q": "The American Federation of Labor was led by:", "options": ["Andrew Carnegie", "Booker T. Washington", "Samuel Gompers", "Eugene Debs"]}, {"q": "The Pullman Strike of 1894 involved:", "options": ["Steel guards", "Farm workers in Florida", "Railroad workers led by Eugene Debs", "Coal miners in Utah"]}, {"q": "A common goal of early unions was:", "options": ["Lower pay", "Longer workdays", "Fewer safety rules", "An eight hour workday"]}, {"q": "The Haymarket Affair took place in:", "options": ["Chicago", "New York", "Boston", "Atlanta"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Workers, Unions and Strikes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,0}'::int[], array[$j$Gompers focused on skilled workers and practical goals.$j$,$j$Federal troops were sent to end it.$j$,$j$The eight hour day later became standard.$j$,$j$A bomb exploded at a labor rally in 1886.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Workers, Unions and Strikes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Immigration and the Growth of Cities$j$, $j${"questions": [{"q": "Most European immigrants entered the United States through:", "options": ["Ellis Island", "Pearl Harbor", "Angel Island", "Jamestown"]}, {"q": "The Chinese Exclusion Act of 1882:", "options": ["Created Ellis Island", "Banned Chinese laborers from immigrating", "Welcomed all immigrants", "Ended slavery"]}, {"q": "Jane Addams founded:", "options": ["Tuskegee Institute", "Hull House", "The AFL", "Standard Oil"]}, {"q": "A nativist was someone who:", "options": ["Opposed immigration", "Led a union", "Owned a railroad", "Welcomed immigrants"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Immigration and the Growth of Cities$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,0}'::int[], array[$j$Ellis Island opened in 1892.$j$,$j$It was the first law to ban a group by nationality.$j$,$j$Hull House helped immigrants in Chicago.$j$,$j$Nativists feared newcomers and wanted limits.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Immigration and the Growth of Cities$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Westward Expansion, Native Americans and the Farmers' Revolt$j$, $j${"questions": [{"q": "The Homestead Act of 1862 offered:", "options": ["Free railroad tickets", "Citizenship for all", "160 acres to families who farmed it", "Free steel"]}, {"q": "The Battle of Little Bighorn (1876) was a victory for:", "options": ["The Nez Perce", "Colonel Custer", "The Confederacy", "Sioux and Cheyenne warriors"]}, {"q": "The Dawes Act of 1887:", "options": ["Broke up tribal lands into individual plots", "Gave Native peoples full land rights", "Ended reservations", "Protected buffalo"]}, {"q": "The Populist Party mainly represented:", "options": ["Steelworkers", "Railroad owners", "Bankers", "Farmers"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Westward Expansion, Native Americans and the Farmers' Revolt$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3}'::int[], array[$j$Settlers had to live on and farm the land for five years.$j$,$j$Custer's force was defeated, but the wars ended in defeat for the Plains nations.$j$,$j$It weakened tribal ownership and cost Native peoples land.$j$,$j$Farmers sought relief from debt and high rates.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Westward Expansion, Native Americans and the Farmers' Revolt$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Gilded Age, Industry, Immigration and the West$j$, $j${"questions": [{"q": "The term Gilded Age was coined by:", "options": ["Booker T. Washington", "Abraham Lincoln", "Teddy Roosevelt", "Mark Twain"]}, {"q": "Standard Oil was built by:", "options": ["J. P. Morgan", "John D. Rockefeller", "Thomas Edison", "Andrew Carnegie"]}, {"q": "The practical electric light bulb was perfected by:", "options": ["Alexander Bell", "Samuel Morse", "Thomas Edison", "Henry Ford"]}, {"q": "Which group focused on skilled workers under Samuel Gompers?", "options": ["Knights of Labor", "Grange", "American Federation of Labor", "Populist Party"]}, {"q": "Ellis Island opened in:", "options": ["1776", "1920", "1892", "1865"]}, {"q": "Wounded Knee (1890) was a tragedy for the:", "options": ["Exodusters", "Cowboys", "Lakota Sioux", "Chinese immigrants"]}, {"q": "The Populist Party was formed in:", "options": ["1892", "1861", "1776", "1920"]}, {"q": "William Jennings Bryan's famous 1896 speech was called:", "options": ["I Have a Dream", "Cross of Gold", "Gettysburg Address", "Four Freedoms"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Gilded Age, Industry, Immigration and the West$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,2,2,2,2,0,1}'::int[], array[$j$It meant gold on the surface hiding problems.$j$,$j$Rockefeller dominated the oil industry.$j$,$j$Edison's 1879 bulb and lab led to modern electric power.$j$,$j$The AFL aimed at wages, hours and conditions.$j$,$j$It processed millions of immigrants.$j$,$j$About 150 Lakota were killed by soldiers.$j$,$j$Farmers organized a political party.$j$,$j$Bryan spoke for farmers against the gold standard.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Gilded Age, Industry, Immigration and the West$j$ on conflict (item_id) do nothing;
